head.script:
scwin.init = function() {
    var jsonData = [{
            "col1": "sample1",
            "col2": "sample2_1",
            "col3": "sample3_1",
            "col4": "sample4_1"
        },
        {
            "col1": "sample1",
            "col2": "sample2_1",
            "col3": "sample3_1",
            "col4": "sample4_1"
        },
        {
            "col1": "sample1",
            "col2": "sample2_2",
            "col3": "sample3_1",
            "col4": "sample4_1"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.__isMerged = function() {
    var rows = WebSquare.wUnit.getJq(".grid_body_row").not(".w2grid_hidedRow");
    return scwin.__isMergedRow(rows, 0) && scwin.__isMergedRow(rows, 1) && !scwin.__isMergedRow(rows, 2);
}
scwin.__isMergedRow = function(rows, index) {
    var count = 0;
    var tds = WebSquare.wUnit.getJq(rows[index]).find('td');
    var dataColmerged = WebSquare.util.getDataPrefix("colmerged");
    for (var i = 0; i < tds.length; i++) {
        var colMerged = parseInt(WebSquare.wUnit.getJq(tds[i]).attr(dataColmerged));
        if (!index) {
            var hasBB = WebSquare.wUnit.getJq(tds[i]).css("border-bottom-width");
            if (hasBB != "0px") {
                return false;
            }
        } else if (index == 1) {
            if (!colMerged) {
                return false;
            }
        } else {
            if (colMerged) {
                count++;
            }
        }
    }
    if (index == 2) {
        return count != 0;
    }
    return true;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일 실행 후 결과를 확인한다.
    //1. Execute the sample file and check the result.
    //WebSquare.wUnit.addCommand("set", "");
    // verify step 1. 그리드뷰의 첫번째 row와 두번째 row가 Merge되어 보여진다.(이전에는 각 컬럼의 값이 같으면 Merge됨)
    //1. The first row and the second row of the grid view are merged (previously merged if the values of each column are the same)
    WebSquare.wUnit.addCommand("assert", "scwin.__isMerged()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 07-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
